I don't use RPG Maker MZ, I do use RPG Maker MV, so I can only provide You help based on the MV version of the RPGM, here is how You can ( how I set ) window size, it will at the same time expand render view and viewport size:
JavaScript:
qWindow_Setup(){
    // Values I just set by default... didn't rly looked into what they
    // really does... but just call them every time xD
    Graphics._width            =this.qWindow_Width;
    Graphics._height           =this.qWindow_Height;
    Graphics.boxWidth          =this.qWindow_Width;
    Graphics.boxHeight         =this.qWindow_Height;
    SceneManager._screenWidth  =this.qWindow_Width;
    SceneManager._screenHeight =this.qWindow_Height;
    SceneManager._boxWidth     =this.qWindow_Width;
    SceneManager._boxHeight    =this.qWindow_Height;
    // actuall function to resize window, it should just move
    // the game window and have nothing to do with rendering
    window.resizeTo(this.qWindow_Width, this.qWindow_Height);}
Now, to read user input... You can make another duplicate of EventListener...
Don't worry, RPG Maker already made multiple duplicates ( each burn a bit of CPU time )
JavaScript:
document.addEventListener("keydown",   (_E)=>this.qHandleKeyEvent(_E,true));
        document.addEventListener("keyup",     (_E)=>this.qHandleKeyEvent(_E,false));
And then You ofc. need a function that would handle the event, in my case it is just a function called "qHandleKeyEvent"
You could do something like:
JavaScript:
qHandleKeyEvent(_E,_IsPressed){
        const _Key=_E.keyCode;
        if(_Key==117){
            // Pressed F6
            // resize window
        }
    }
You can get KeyCodes from website like:
https://www.toptal.com/developers/keycode
Now... if You want to make it whole... here is full code that would do it for You:
JavaScript:
class qlResizeWindowKey{
    constructor(){
        Object.assign(this,{
            // Size of the Window in "Small" size in pixels
            qWindow_Width_Min  : 1360,
            qWindow_Height_Min :  768,

            // Size of the Window in "Big" size in pixels
            qWindow_Width_Max  : 1920,
            qWindow_Width_Min  : 1080,

            qIsFullMode        : 0 // Starting Mode - 0 for Small, 1 for Big
        });

        document.addEventListener("keyup",     (_E)=>this.qHandleKeyEvent(_E));
    }

    qHandleKeyEvent(_E){
        const _KeyCode = _E.keyCode;
        if( _KeyCode == 117 ){ // if F6 got pressed
            if(qIsFullMode == 0 ){ // if we are in small window set to big ( MAX )
                qSetWindow( this.qWindow_Width_Max, this.qWindow_Height_Max );
            }else{                 // Else, we must be in Big window, so set to small
                qSetWindow( this.qWindow_Width_Min, this.qWindow_Height_Min );
            }
        }
    }

    qSetWindow(_X,_Y){
        Graphics._width            =_X;
        Graphics._height           =_Y;
        Graphics.boxWidth          =_X;
        Graphics.boxHeight         =_Y;
        SceneManager._screenWidth  =_X;
        SceneManager._screenHeight =_Y;
        SceneManager._boxWidth     =_X;
        SceneManager._boxHeight    =_Y;
        window.resizeTo(_X, _Y);
    }
}
var qResizeWK = new qlResizeWindowKey();
Now, You can copy above and create new file with extension .js in Your plugins folder,
then in RPG Maker add Your plugin to the Engine / Project / Game and it's all, script already handles everything else...
That is assuming that MZ can work similar to MV...
And I need to tell You that this code does not MOVE window to the middle of the screen...
I didn't needed moving window yet ( cuz I'm still early in dev of my own game on RPGM )
But if that code works, then let me know, Ill upgrade it for You to also move the window to the middle of the screen

The game calls this on boot:
JavaScript:
Scene_Boot.prototype.adjustWindow = function() {
    if (Utils.isNwjs()) {
        const scale = this.screenScale();
        const xDelta = Graphics.width * scale - window.innerWidth;
        const yDelta = Graphics.height * scale - window.innerHeight;
        window.moveBy(-xDelta / 2, -yDelta / 2);
        window.resizeBy(xDelta, yDelta);
    }
};
By default this is the only time the game checks and applies the Database
screenScale
value.
For what you've asked, something like this might do the trick (untested):
Spoiler:
plugin code
JavaScript:
/*:
 * @target MZ
 * @plugindesc Resize screen in integer steps when pressing F6.
 * @author Caethyril
 * @url https://forums.rpgmakerweb.com/threads/174689/
 * @help Free to use and/or modify for any project, no credit required.
 */
;void (() => {
"use strict";
  /** Identifier for new "scale multiplier" property on {@linkcode multObj}. */
  const P = Symbol();

  /** @returns {object} Object on which {@linkcode P} property is present. */
  const multObj = function() { return Graphics; };

  /**
   * Updates NWJS window scale/position.
   * @param {number} w Target width.
   * @param {number} h Target height.
   */
  const updateScale = function(w, h) {
    if (!w || !h)
      return;
    const dx = w - window.innerWidth;
    const dy = h - window.innerHeight;
    window.moveBy(-dx >> 1, -dy >> 1);
    window.resizeBy(dx, dy);
    alert("resized!");  // for testing
  };

  /**
   * @param {number} scale Scale value.
   * @returns {[number, number]} Scaled game width and height.
   */
  const getScaledSize = function(scale = 1) {
    return [Graphics.width * scale, Graphics.height * scale];
  };

  /**
   * Sets scale multiplier to given value and updates window size.
   * @param {number} scale Value to set for scale multiplier.
   */
  globalThis.setScaleMultiplier = function(scale = 1) {
    if (Utils.isNwjs())
      updateScale(...getScaledSize(multObj()[P] = scale));
  };

  /**
   * Increments scale multiplier, resets to 1 if over-sized, and updates window size.
   * @param {number} [plus=1] Optional, default 1. Value to add to scale multiplier.
   */
  globalThis.addScaleMultiplier = function(plus = 1) {
    if (!Utils.isNwjs())
      return;
    const scale = $dataSystem.advanced.screenScale ?? 1;
    // Size check based on screen ID 0.
    const { width, height } = require("nw.gui").Screen.screens[0].bounds;
    const iw = window.innerWidth;
    const ih = window.innerHeight;
    const dw = window.outerWidth - iw;
    const dh = window.outerHeight - ih;
    const o = multObj();
    let [ w, h ] = getScaledSize(scale * (o[P] += plus));
    if (w + dw > width || h + dh > height)
      [ w, h ] = getScaledSize(scale * (o[P] = 1));
    updateScale(w, h);
  };

  // Patch - init custom scale multiplier
  void (alias => {
    Graphics.initialize = function() {
      this[P] = 1;
      return alias.apply(this, arguments);
    };
  })(Graphics.initialize);

  // Patch - increment/reset multiplier when F6 is pressed.
  void (alias => {
    Graphics._onKeyDown = function(e) {
      if (!e.ctrlKey && !e.altKey && e.keyCode === 117)  // F6
        addScaleMultiplier();
      else
        alias.apply(this, arguments);
    };
  })(Graphics._onKeyDown);

})();
Corresponding script calls would be like
setScaleMultiplier(2)
or
addScaleMultiplier()
.
I did a little searching but didn't find a way to reliably identify the screen where the game app is currently (
reference
), so I've simply based the upper bound on the size of the first screen.
